import React from 'react';
import KPISection from './KPISection';
import ChartsSection from './ChartsSection';
import TablesSection from './TablesSection';
import { SalesRecord } from '../types';
import {
  calculateKPIs,
  getTopProducts,
  getTopCustomers,
  getMonthlyData,
  getProductShare
} from '../utils/calculations';

interface DashboardProps {
  salesData: SalesRecord[];
}

const Dashboard: React.FC<DashboardProps> = ({ salesData }) => {
  const kpiData = calculateKPIs(salesData);
  const topProducts = getTopProducts(salesData);
  const topCustomers = getTopCustomers(salesData);
  const monthlyData = getMonthlyData(salesData);
  const productShare = getProductShare(salesData);

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">Sales & Revenue Dashboard</h1>
          <p className="mt-2 text-gray-600">
            Track sales performance, compare monthly sales with targets, and identify top-performing products and customers.
          </p>
        </div>

        {/* KPIs Section */}
        <KPISection kpiData={kpiData} />

        {/* Charts Section */}
        <ChartsSection 
          monthlyData={monthlyData}
          productShare={productShare}
          topCustomers={topCustomers}
        />

        {/* Tables Section */}
        <TablesSection 
          topProducts={topProducts}
          topCustomers={topCustomers}
        />
      </div>
    </div>
  );
};

export default Dashboard;
